package com.consense.service.drafting;

import com.consense.common.JsonUtils;
import com.consense.document.DocxTemplateEditor;
import com.consense.document.DocxTemplateEditor.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class DraftClearedNativeLayoutStateTest {
    private final DocxTemplateEditor editor=new DocxTemplateEditor();
    byte[] packageXml(String xml)throws Exception{try(ByteArrayOutputStream out=new ByteArrayOutputStream();ZipOutputStream zip=new ZipOutputStream(out)){zip.putNextEntry(new ZipEntry("word/document.xml"));zip.write(xml.getBytes(StandardCharsets.UTF_8));zip.closeEntry();zip.putNextEntry(new ZipEntry("[Content_Types].xml"));zip.write("<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/></Types>".getBytes(StandardCharsets.UTF_8));zip.closeEntry();zip.finish();return out.toByteArray();}}
    String xml(byte[] bytes)throws Exception{try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes))){zip.getNextEntry();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=zip.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
    DocxEditResult saved()throws Exception{
        byte[] source=packageXml("<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body><w:p><w:r><w:t>SCC8.303 Not used</w:t></w:r></w:p><w:p><w:pPr><w:spacing w:after=\"120\"/></w:pPr></w:p><w:p><w:r><w:t>SCC5.308 Retained heading</w:t></w:r></w:p></w:body></w:document>");TemplateIndex index=editor.inspect(source);NativeLayoutPlan layout=new NativeLayoutPlan(index.getSourceSha256(),"test-scc-layout",Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),Collections.singletonList(new NativeLayoutClearedParagraph(index.anchor(index.mainParagraph(2).getId()),index.anchor(index.mainParagraph(1).getId()),"SCC8.303Not used",false)),Collections.singletonList(index.anchor(index.mainParagraph(3).getId())));return editor.applyWithParagraphBookmarks(source,new SourceEditBatch(index.getSourceSha256(),Collections.emptyList()),Collections.emptyMap(),false,layout);
    }
    Map<String,Object> state(DocxEditResult saved,byte[] bytes){Map<String,Object> original=DraftNativeLayout.info("SCC","libreoffice",saved);DocxEditResult updated=editor.apply(bytes,new SourceEditBatch(editor.inspect(bytes).getSourceSha256(),Collections.emptyList()));return DraftBusinessRules.asMap(DraftNativeLayout.bodyLedger(JsonUtils.write(Collections.singletonList(original)),updated).stream().filter(raw->"native_layout".equals(DraftBusinessRules.asMap(raw).get("kind"))).findFirst().get());}
    @Test void survivingSourceMarkersRetainBothNewNativeControlClaims()throws Exception{DocxEditResult saved=saved();Map<String,Object> row=state(saved,saved.getDocxBytes());assertEquals("applied",row.get("status"));assertEquals("test-scc-layout",row.get("profile"));assertEquals(2,DraftBusinessRules.list(row.get("actions")).size());for(Object raw:DraftBusinessRules.list(row.get("actions")))assertEquals("APPLIED",DraftBusinessRules.asMap(raw).get("status"));}
    @Test void removedPaddingOrHeadingMarkersInvalidateTheirSavedLayoutClaim()throws Exception{DocxEditResult saved=saved();for(NativeLayoutChange change:saved.getNativeLayoutLedger()){String text=xml(saved.getDocxBytes());text=text.replaceAll("<w:bookmarkStart[^>]*w:name=\""+change.getLayoutId()+"\"[^>]*/>","");Map<String,Object> row=state(saved,packageXml(text));assertEquals("unavailable",row.get("status"));assertTrue(DraftBusinessRules.list(row.get("actions")).stream().map(DraftBusinessRules::asMap).anyMatch(a->"MISSING_LAYOUT_CONTROL".equals(a.get("status"))));}}
    @Test void changedPaddingAndKeepNextPropertiesInvalidateTheirSavedLayoutClaim()throws Exception{DocxEditResult saved=saved();for(String text:Arrays.asList(xml(saved.getDocxBytes()).replace("w:line=\"1\"","w:line=\"900\""),xml(saved.getDocxBytes()).replace("<w:keepNext w:val=\"1\"/>","<w:keepNext w:val=\"0\"/>"))){Map<String,Object> row=state(saved,packageXml(text));assertEquals("unavailable",row.get("status"));assertTrue(DraftBusinessRules.list(row.get("actions")).stream().map(DraftBusinessRules::asMap).anyMatch(a->"CHANGED_LAYOUT_CONTROL".equals(a.get("status"))));}}
    @Test void headingBoundaryStateTracksItsPropertyAndInvisibleSourceMarker()throws Exception{byte[] source=packageXml("<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body><w:p><w:r><w:t>Retained heading</w:t></w:r></w:p><w:p/><w:p><w:r><w:t>Retained first body</w:t></w:r></w:p></w:body></w:document>");TemplateIndex index=editor.inspect(source);NativeLayoutPlan layout=new NativeLayoutPlan(index.getSourceSha256(),"exact-heading-break",Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),Collections.singletonList(new NativeLayoutParagraphBoundary(index.anchor(index.mainParagraph(1).getId()),index.anchor(index.mainParagraph(3).getId()),Collections.singletonList(index.anchor(index.mainParagraph(2).getId())))));DocxEditResult saved=editor.applyWithParagraphBookmarks(source,new SourceEditBatch(index.getSourceSha256(),Collections.emptyList()),Collections.emptyMap(),false,layout);assertEquals("applied",state(saved,saved.getDocxBytes()).get("status"));String text=xml(saved.getDocxBytes());assertEquals("unavailable",state(saved,packageXml(text.replace("<w:pageBreakBefore w:val=\"1\"/>","<w:pageBreakBefore w:val=\"0\"/>"))).get("status"));assertEquals("unavailable",state(saved,packageXml(text.replaceAll("<w:bookmarkStart[^>]*w:name=\""+saved.getNativeLayoutLedger().get(0).getLayoutId()+"\"[^>]*/>",""))).get("status"));}
}
